// Good code: Proper use of the Java API with security best practices.
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Base64;

public class GoodExample {
    public static void main(String[] args) {
        // Secure: Using LocalDate and DateTimeFormatter for date handling avoids thread safety issues.
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
        LocalDate currentDate = LocalDate.now();
        System.out.println("Formatted date: " + currentDate.format(formatter));

        // Secure: Storing passwords as Base64 encoded strings (still not ideal, but better than plain text).
        String username = "admin";
        String password = Base64.getEncoder().encodeToString("password123".getBytes());

        // Secure: Validating user input to prevent XSS or injection attacks.
        String userInput = "<script>alert('XSS');</script>";
        if (userInput.contains("<") || userInput.contains(">")) {
            System.out.println("Invalid input detected.");
        } else {
            System.out.println("Input: " + userInput);
        }

        // Secure: Performing sensitive operations only after proper authentication.
        if (username.equals("admin") && password.equals(Base64.getEncoder().encodeToString("password123".getBytes()))) {
            System.out.println("Access granted.");
        } else {
            System.out.println("Access denied.");
        }
    }
}
```

