// Corretto: gestione delle eccezioni specifica e sicura, senza rivelare dettagli tecnici al client
public void processRequest(String input) {
    try {
        // Simulazione di un processo che potrebbe lanciare un'eccezione
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input non valido");
        }
        // Altri processi...
    } catch (IllegalArgumentException e) {
        // Gestione specifica per errori di input
        System.out.println("Errore di input: " + e.getMessage());
    } catch (Exception e) {
        // Gestione generica per altre eccezioni, senza rivelare dettagli tecnici
        System.out.println("Si è verificato un errore. Riprova più tardi.");
    }
}
